const SORTABLE = ["id", "title", "createdAt"];

function parseSort(sort) {
  const text = sort ?? "id";
  const field = text.replace(/^-/, "");
  if (!SORTABLE.includes(field)) return null;
  return { field, desc: text.startsWith("-") };
}

console.log(parseSort(null));
console.log(parseSort("-createdAt"));
console.log(parseSort("title"));
console.log(parseSort("-password"));

