const ids = [1, 2, 3, 4, 5, 6, 7];

function page(limit, before = Infinity) {
  const rows = ids.filter((id) => id < before).toSorted((a, b) => b - a).slice(0, limit + 1);
  const data = rows.slice(0, limit);
  return { data, next: rows.length > limit ? data.at(-1) : null };
}

const p1 = page(3);
const p2 = page(3, p1.next);
const p3 = page(3, p2.next);
console.log(p1, p2, p3);

