function nextLink(path, limit, offset, total) {
  if (offset + limit >= total) return null;
  const params = new URLSearchParams({ limit: String(limit), offset: String(offset + limit) });
  return `${path}?${params}`;
}

console.log(nextLink("/v1/tasks", 2, 0, 5));
console.log(nextLink("/v1/tasks", 2, 2, 5));
